import java.util.*;

class Node {
    int data;
    Node next;

    Node(int d) {
        data = d;
        next = null;
    }
}

public class Solution {

    static Node buildList(String[] arr) {
        Node head = null, tail = null;

        for (String s : arr) {
            if (s.length() == 0)
                continue;

            Node newNode = new Node(Integer.parseInt(s));

            if (head == null) {
                head = newNode;
                tail = newNode;
            } else {
                tail.next = newNode;
                tail = newNode;
            }
        }

        return head;
    }

    static int compareLists(Node head1, Node head2) {
        while (head1 != null && head2 != null) {
            if (head1.data != head2.data)
                return 0;

            head1 = head1.next;
            head2 = head2.next;
        }

        return (head1 == null && head2 == null) ? 1 : 0;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        String input = sc.nextLine();
        String[] parts = input.split("\\|");

        String[] list1 = parts[0].trim().split("\\s+");
        String[] list2 = parts[1].trim().split("\\s+");

        Node head1 = buildList(list1);
        Node head2 = buildList(list2);

        System.out.print(compareLists(head1, head2));
    }
}

