        String[] input = sc.nextLine().trim().split("\\s+");
        int[] arr = new int[input.length];

        for (int i = 0; i < input.length; i++) {
            arr[i] = Integer.parseInt(input[i]);
        }

        ListNode head = buildList(arr);

        System.out.print(middleNode(head));
    }
}

