import java.util.*;

class ListNode {
    int val;
    ListNode next;

    ListNode(int val) {
        this.val = val;
        this.next = null;
    }
}

public class Solution {

    static ListNode buildList(int[] arr) {
        ListNode head = null, tail = null;

        for (int x : arr) {
            ListNode node = new ListNode(x);

            if (head == null) {
                head = node;
                tail = node;
            } else {
                tail.next = node;
                tail = node;
            }
        }

        return head;
    }

    static int numComponents(ListNode head, int[] nums) {
        Set<Integer> set = new HashSet<>();

        for (int n : nums)
            set.add(n);

        int count = 0;

        while (head != null) {
            if (set.contains(head.val) &&
                (head.next == null || !set.contains(head.next.val)))
                count++;

            head = head.next;
        }

        return count;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        String s = sc.nextLine().trim();
        String[] parts = s.split(",");

        String listPart = parts.length > 0 ? parts[0].split(":", 2)[1].trim() : "";
        String numsPart = parts.length > 1 ? parts[1].split(":", 2)[1].trim() : "";

        String[] a = listPart.isEmpty() ? new String[0] : listPart.split("\\s+");
        String[] b = numsPart.isEmpty() ? new String[0] : numsPart.split("\\s+");

        int[] listValues = new int[a.length];
        int[] nums = new int[b.length];

        for (int i = 0; i < a.length; i++)
            listValues[i] = Integer.parseInt(a[i]);

        for (int i = 0; i < b.length; i++)
            nums[i] = Integer.parseInt(b[i]);

        ListNode head = buildList(listValues);

        System.out.print(numComponents(head, nums));
    }
}

