void nodesBetweenCriticalPoints(struct ListNode* head, int result[2]) {
    struct ListNode* prev = head;
    struct ListNode* curr = head->next;

    int pos = 1;
    int first = -1, last = -1;
    int minDist = INT_MAX;

    while (curr->next != NULL) {
        pos++;

        if ((curr->val > prev->val && curr->val > curr->next->val) ||
            (curr->val < prev->val && curr->val < curr->next->val)) {

            if (first == -1)
                first = pos;
            else if (pos - last < minDist)
                minDist = pos - last;

            last = pos;
        }

        prev = curr;
        curr = curr->next;
    }

    if (first == -1 || first == last) {
        result[0] = -1;
        result[1] = -1;
    } else {
        result[0] = minDist;
        result[1] = last - first;
    }
}

