                minDist = min(minDist, pos - prevCritical);

            prevCritical = pos;
            maxDist = pos - first;
        }

        prev = head;
        head = head->next;
    }

    if (minDist != INT_MAX)
        res = {minDist, maxDist};

    return res;
}

