}

public class Solution {

    static ListNode buildList(int[] values) {
        if (values.length == 0) {
            return null;
        }

        ListNode head = new ListNode(values[0]);
        ListNode current = head;

        for (int i = 1; i < values.length; i++) {
            current.next = new ListNode(values[i]);
            current = current.next;
        }

        return head;
    }

    static TreeNode buildTree(String[] values) {
        if (values.length == 0 || values[0].trim().equals("null")) {
            return null;
        }

        TreeNode root = new TreeNode(Integer.parseInt(values[0].trim()));
        Queue<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);

        int index = 1;

        while (!queue.isEmpty() && index < values.length) {
            TreeNode current = queue.poll();

            if (index < values.length && !values[index].trim().equals("null")) {
                current.left = new TreeNode(Integer.parseInt(values[index].trim()));
                queue.offer(current.left);
            }
            index++;

            if (index < values.length && !values[index].trim().equals("null")) {
                current.right = new TreeNode(Integer.parseInt(values[index].trim()));
                queue.offer(current.right);
            }
            index++;
        }

        return root;
    }

    static boolean matches(ListNode head, TreeNode node) {
        if (head == null) {
            return true;
        }

        if (node == null) {
            return false;
        }

        if (head.val != node.val) {
            return false;
        }

        return matches(head.next, node.left) ||
               matches(head.next, node.right);
    }

    static boolean isSubPath(ListNode head, TreeNode root) {
        if (head == null) {
            return true;
        }

        if (root == null) {
            return false;
        }

        if (matches(head, root)) {
            return true;
        }

        return isSubPath(head, root.left) ||
               isSubPath(head, root.right);
    }

    static List<Integer> extractListValues(String input) {
        List<Integer> values = new ArrayList<>();

        int colon = input.indexOf(':');
        int treePos = input.indexOf(", tree:");

        if (colon == -1 || treePos == -1) {
            return values;
        }

        String part = input.substring(colon + 1, treePos).trim();

        if (part.isEmpty()) {
            return values;
        }

        String[] tokens = part.split("\\s+");

        for (String token : tokens) {
            values.add(Integer.parseInt(token));
        }

        return values;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        StringBuilder input = new StringBuilder();

        while (scanner.hasNextLine()) {
            input.append(scanner.nextLine());
        }

        String text = input.toString().trim();

        int treeMarker = text.indexOf(", tree:");

        if (treeMarker == -1) {
            System.out.print("false");
            return;
        }

        List<Integer> listValues = extractListValues(text);

        int open = text.indexOf('[', treeMarker);
        int close = text.lastIndexOf(']');

        if (open == -1 || close == -1 || close < open) {
            System.out.print("false");
            return;
        }

        String treePart = text.substring(open + 1, close).trim();

        String[] treeValues = treePart.isEmpty()
                ? new String[0]
                : treePart.split(",");

        int[] listArray = new int[listValues.size()];

        for (int i = 0; i < listValues.size(); i++) {
            listArray[i] = listValues.get(i);
        }

        ListNode head = buildList(listArray);
        TreeNode root = buildTree(treeValues);

        System.out.print(isSubPath(head, root) ? "true" : "false");
    }
}

