from functools import lru_cache

class Solution:
    def minPairRemovals(self, nums):
        if isinstance(nums, str):
            arr = [int(x) for x in nums.strip().split()]
        else:
            arr = list(nums)
            if len(arr) > 0 and isinstance(arr[0], str):
                arr = [int(x) for x in arr]

        if len(arr) > 0:
            arr = arr[1:]

        def is_sorted(a):
            for i in range(1, len(a)):
                if a[i] < a[i - 1]:
                    return False
            return True

        @lru_cache(None)
        def solve(state):
            state = tuple(state)

            if len(state) <= 1 or is_sorted(state):
                return 0

            best = float('inf')

            for i in range(len(state) - 1):
                nxt = state[:i] + state[i + 2:]
                best = min(best, 1 + solve(nxt))

            return best

        return solve(tuple(arr))

