import java.util.*;

class Fenwick {
    int n;
    int[] bit;

    Fenwick(int n) {
        this.n = n;
        this.bit = new int[n + 1];
    }

    void update(int idx, int val) {
        while (idx <= n) {
            bit[idx] = Math.max(bit[idx], val);
            idx += idx & -idx;
        }
    }

    int query(int idx) {
        int ans = 0;
        while (idx > 0) {
            ans = Math.max(ans, bit[idx]);
            idx -= idx & -idx;
        }
        return ans;
    }
}

public class Solution {

    static int lowerBound(int[] arr, int size, int target) {
        int left = 0, right = size;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    static int solve(int[] nums) {
        int n = nums.length;

        if (n <= 1) {
            return 0;
        }

        int[] vals = nums.clone();
        Arrays.sort(vals);

        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || vals[i] != vals[i - 1]) {
                vals[m++] = vals[i];
            }
        }

        Fenwick oddTree = new Fenwick(m);
        Fenwick evenTree = new Fenwick(m);

        int bestKeep = (n % 2 == 0) ? 0 : 1;

        for (int i = 0; i < n; i++) {
            int pos = lowerBound(vals, m, nums[i]) + 1;
            int dp = 0;
            int parity = (i + 1) % 2;

            if (parity == 1) {
                dp = Math.max(1, evenTree.query(pos) + 1);
                oddTree.update(pos, dp);
            } else {
                int prev = oddTree.query(pos);
                if (prev > 0) {
                    dp = prev + 1;
                    evenTree.update(pos, dp);
                }
            }

            if (((i + 1) % 2) == (n % 2)) {
                bestKeep = Math.max(bestKeep, dp);
            }
        }

        return (n - bestKeep) / 2;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        ArrayList<Integer> list = new ArrayList<>();
        String line;

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;

            String[] parts = line.split("\\s+");
            for (String part : parts) {
                list.add(Integer.parseInt(part));
            }
        }

        if (list.size() <= 1) {
            System.out.print(0);
            return;
        }

        int[] nums = new int[list.size() - 1];
        for (int i = 1; i < list.size(); i++) {
            nums[i - 1] = list.get(i);
        }

        System.out.print(solve(nums));
    }
}

#include <stdio.h>
#include <stdlib.h>

int isSorted(int arr[], int n) {
    for (int i = 1; i < n; i++) {
        if (arr[i] < arr[i - 1]) {
            return 0;
        }
    }
    return 1;
}

int solve(int arr[], int n) {
    if (n <= 1 || isSorted(arr, n)) {
        return 0;
    }

    int best = n / 2;

    for (int i = 0; i < n - 1; i++) {
        int *next = (int *)malloc((n - 2) * sizeof(int));
        int idx = 0;

        for (int j = 0; j < n; j++) {
            if (j == i || j == i + 1) continue;
            next[idx++] = arr[j];
        }

        int ops = 1 + solve(next, n - 2);
        if (ops < best) {
            best = ops;
        }

        free(next);
    }

    return best;
}

