public class Solution {

    static class Node {
        int val;
        Node next;

        Node(int val) {
            this.val = val;
        }
    }

    static Node insert(Node head, int value) {
        Node newNode = new Node(value);

        if (head == null) {
            newNode.next = newNode;
            return newNode;
        }

        Node curr = head;

        while (true) {
            Node nextNode = curr.next;

            if (curr.val <= value && value <= nextNode.val) {
                break;
            }

            if (curr.val > nextNode.val) {
                if (value >= curr.val || value <= nextNode.val) {
                    break;
                }
            }

            curr = nextNode;

            if (curr == head) {
                break;
            }
        }

        newNode.next = curr.next;
        curr.next = newNode;

        return head;
    }

    static Node buildCircularList(List<Integer> values) {
        if (values.isEmpty()) {
            return null;
        }

        Node head = new Node(values.get(0));
        Node tail = head;

        for (int i = 1; i < values.size(); i++) {
            Node node = new Node(values.get(i));
            tail.next = node;
            tail = node;
        }

        tail.next = head;
        return head;
    }

    static void printSortedList(Node head) {
        if (head == null) {
            return;
        }

        Node start = head;
        Node curr = head.next;

        while (curr != head) {
            if (curr.val < start.val) {
                start = curr;
            }
            curr = curr.next;
        }

        curr = start;
        StringBuilder result = new StringBuilder();

        do {
            if (result.length() > 0) {
                result.append(" ");
            }

            result.append(curr.val);
            curr = curr.next;
        } while (curr != start);

        System.out.println(result);
    }

