        Scanner sc = new Scanner(System.in);

        StringBuilder input = new StringBuilder();

        while (sc.hasNextLine()) {
            input.append(sc.nextLine()).append(" ");
        }

        String data = input.toString();

        Matcher valueMatcher = Pattern
                .compile("value:\\s*(-?\\d+)")
                .matcher(data);

        if (!valueMatcher.find()) {
            return;
        }

        int insertValue = Integer.parseInt(valueMatcher.group(1));

        List<Integer> values = new ArrayList<>();

        Matcher listMatcher = Pattern
                .compile("list:\\s*(.*?)\\s*\\(circular\\)")
                .matcher(data);

        if (listMatcher.find()) {
            String listPart = listMatcher.group(1);

            Matcher numberMatcher = Pattern
                    .compile("-?\\d+")
                    .matcher(listPart);

            while (numberMatcher.find()) {
                values.add(Integer.parseInt(numberMatcher.group()));
            }
        }

        Node head = buildCircularList(values);
        head = insert(head, insertValue);
        printSortedList(head);
    }
}

