        int list1Start = s.indexOf("list1:") + 6;
        int startPos = s.indexOf("start:");
        int endPos = s.indexOf("end:");
        int list2Pos = s.indexOf("list2:");

        int start = Integer.parseInt(
                s.substring(startPos + 6, s.indexOf(",", startPos)).trim()
        );
        int end = Integer.parseInt(
                s.substring(endPos + 4, s.indexOf(",", endPos)).trim()
        );

        String list1Text = s.substring(list1Start, startPos)
                .replace(",", "")
                .trim();
        String list2Text = s.substring(list2Pos + 6).trim();

        int[] list1Values = parseNumbers(list1Text);
        int[] list2Values = parseNumbers(list2Text);

        ListNode list1 = buildList(list1Values);
        ListNode list2 = buildList(list2Values);
        ListNode result = mergeInBetween(list1, start, end, list2);

        StringBuilder output = new StringBuilder();
        while (result != null) {
            if (output.length() > 0) output.append(" ");
            output.append(result.val);
            result = result.next;
        }

        System.out.println(output);
    }
}

