using namespace std;

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int value) : val(value), next(nullptr) {}
};

ListNode* buildList(const vector<int>& values) {
    ListNode dummy(0);
    ListNode* tail = &dummy;

    for (int value : values) {
        tail->next = new ListNode(value);
        tail = tail->next;
    }

    return dummy.next;
}

ListNode* mergeInBetween(ListNode* list1, int start, int end, ListNode* list2) {
    ListNode dummy(0);
    dummy.next = list1;

    ListNode* before = &dummy;
    for (int i = 0; i < start; i++) {
        before = before->next;
    }

    ListNode* after = before->next;
    for (int i = start; i <= end; i++) {
        after = after->next;
    }

    before->next = list2;

    ListNode* tail = list2;
    while (tail->next != nullptr) {
        tail = tail->next;
    }

    tail->next = after;
    return dummy.next;
}

vector<int> extractNumbers(const string& text) {
    vector<int> values;
    size_t i = 0;

    while (i < text.size()) {
        while (i < text.size() && !isdigit((unsigned char)text[i]) && text[i] != '-') {
            i++;
        }
        if (i >= text.size()) break;

        int sign = 1;
        if (text[i] == '-') {
            sign = -1;
            i++;
        }

        int value = 0;
        while (i < text.size() && isdigit((unsigned char)text[i])) {
            value = value * 10 + (text[i] - '0');
            i++;
        }
        values.push_back(sign * value);
    }

    return values;
}

int extractValue(const string& input, const string& key) {
    size_t pos = input.find(key);
    if (pos == string::npos) return 0;
    pos += key.size();

    while (pos < input.size() && !isdigit((unsigned char)input[pos]) && input[pos] != '-') {
        pos++;
    }

    int sign = 1;
    if (input[pos] == '-') {
        sign = -1;
        pos++;
    }

    int value = 0;
    while (pos < input.size() && isdigit((unsigned char)input[pos])) {
        value = value * 10 + (input[pos] - '0');
        pos++;
    }

    return sign * value;
}

