class Skiplist:
    def __init__(self):
        self.head = Node(-1, MAX_LEVEL)
        self.level = 0

    def random_level(self):
        lvl = 0
        while random.randint(0, 1) and lvl < MAX_LEVEL:
            lvl += 1
        return lvl

    def search(self, target):
        curr = self.head

        for i in range(self.level, -1, -1):
            while curr.forward[i] is not None and curr.forward[i].val < target:
                curr = curr.forward[i]

        curr = curr.forward[0]
        return curr is not None and curr.val == target

    def add(self, num):
        update = [None] * (MAX_LEVEL + 1)
        curr = self.head

        for i in range(self.level, -1, -1):
            while curr.forward[i] is not None and curr.forward[i].val < num:
                curr = curr.forward[i]
            update[i] = curr

        lvl = self.random_level()

        if lvl > self.level:
            for i in range(self.level + 1, lvl + 1):
                update[i] = self.head
            self.level = lvl

        node = Node(num, lvl)

        for i in range(lvl + 1):
            node.forward[i] = update[i].forward[i]
            update[i].forward[i] = node

    def erase(self, num):
        update = [None] * (MAX_LEVEL + 1)
        curr = self.head

        for i in range(self.level, -1, -1):
            while curr.forward[i] is not None and curr.forward[i].val < num:
                curr = curr.forward[i]
            update[i] = curr

        curr = curr.forward[0]

        if curr is None or curr.val != num:
            return False

        for i in range(self.level + 1):
            if update[i].forward[i] != curr:
                break
            update[i].forward[i] = curr.forward[i]

        while self.level > 0 and self.head.forward[self.level] is None:
            self.level -= 1

