public class Solution {

    static List<Operation> parseOperations(String input) {
        List<Operation> ops = new ArrayList<>();
        int n = input.length();

        for (int i = 0; i < n; ) {
            if (Character.isLetter(input.charAt(i))) {
                StringBuilder word = new StringBuilder();

                while (i < n && Character.isLetter(input.charAt(i))) {
                    word.append(Character.toLowerCase(input.charAt(i)));
                    i++;
                }

                String op = word.toString();

                if (op.equals("add") || op.equals("search") || op.equals("erase")) {
                    while (i < n && !(Character.isDigit(input.charAt(i)) || input.charAt(i) == '-')) {
                        i++;
                    }

                    int sign = 1;
                    if (i < n && input.charAt(i) == '-') {
                        sign = -1;
                        i++;
                    }

                    int val = 0;
                    while (i < n && Character.isDigit(input.charAt(i))) {
                        val = val * 10 + (input.charAt(i) - '0');
                        i++;
                    }

                    ops.add(new Operation(op, sign * val));
                }
            } else {
                i++;
            }
        }

        return ops;
    }

