        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder input = new StringBuilder();
        String line;

        while ((line = br.readLine()) != null) {
            input.append(line).append('\n');
        }

        List<Operation> ops = parseOperations(input.toString());

        if (ops.isEmpty()) {
            return;
        }

        Skiplist sk = new Skiplist();
        String answer = "false";

        for (Operation op : ops) {
            if (op.type.equals("add")) {
                sk.add(op.value);
            } else if (op.type.equals("search")) {
                answer = sk.search(op.value) ? "true" : "false";
            } else if (op.type.equals("erase")) {
                answer = sk.erase(op.value) ? "true" : "false";
            }
        }

        System.out.print(answer);
    }
}

