import sys


class ListNode:
    def __init__(self, x):
        self.val = x
        self.next = None


class Solution:
    def addTwoNumbers(self, l1, l2):

        s1 = []
        s2 = []

        while l1:
            s1.append(l1.val)
            l1 = l1.next

        while l2:
            s2.append(l2.val)
            l2 = l2.next

        carry = 0
        head = None

        while s1 or s2 or carry:

            total = carry

            if s1:
                total += s1.pop()

            if s2:
                total += s2.pop()

            node = ListNode(total % 10)
            node.next = head
            head = node

            carry = total // 10

        return head


def parse_array(text):
    nums = []
    i = 0

    while i < len(text):

        if text[i].isdigit() or (text[i] == '-' and i + 1 < len(text) and text[i+1].isdigit()):

            sign = 1
            if text[i] == '-':
                sign = -1
                i += 1

            val = 0
            while i < len(text) and text[i].isdigit():
                val = val * 10 + int(text[i])
                i += 1

            nums.append(sign * val)

        else:
            i += 1

    return nums


def extract_arrays(text):

    arrays = []
    i = 0

    while i < len(text):

        if text[i] == '[':

            j = i + 1
            depth = 1

            while j < len(text) and depth > 0:

                if text[j] == '[':
                    depth += 1
                elif text[j] == ']':
                    depth -= 1

                j += 1

            part = text[i:j]

            if any(c.isdigit() for c in part):
                arrays.append(parse_array(part))

            i = j

        else:
            i += 1

    return arrays


def build_list(nums):

    head = None
    tail = None

    for x in nums:

        node = ListNode(x)

        if head is None:
            head = tail = node
        else:
            tail.next = node
            tail = node

