using namespace std;

class ListNode {
public:
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(NULL) {}
};

class Solution {
public:
    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
        stack<int> s1, s2;

        while (l1) {
            s1.push(l1->val);
            l1 = l1->next;
        }

        while (l2) {
            s2.push(l2->val);
            l2 = l2->next;
        }

        int carry = 0;
        ListNode* head = NULL;

        while (!s1.empty() || !s2.empty() || carry) {
            int sum = carry;

            if (!s1.empty()) {
                sum += s1.top();
                s1.pop();
            }

            if (!s2.empty()) {
                sum += s2.top();
                s2.pop();
            }

            ListNode* node = new ListNode(sum % 10);
            node->next = head;
            head = node;

            carry = sum / 10;
        }

        return head;
    }
};

vector<int> parseOneArray(const string& s) {
    vector<int> nums;
    int n = (int)s.size();

    for (int i = 0; i < n; ) {
        if (isdigit((unsigned char)s[i]) || (s[i] == '-' && i + 1 < n && isdigit((unsigned char)s[i + 1]))) {
            int sign = 1;
            if (s[i] == '-') {
                sign = -1;
                i++;
            }

            int val = 0;
            while (i < n && isdigit((unsigned char)s[i])) {
                val = val * 10 + (s[i] - '0');
                i++;
            }

            nums.push_back(sign * val);
        } else {
            i++;
        }
    }

    return nums;
}

vector<vector<int>> extractBracketArrays(const string& s) {
    vector<vector<int>> arrays;
    int n = (int)s.size();

    for (int i = 0; i < n; i++) {
        if (s[i] != '[') continue;

        int j = i + 1;
        int depth = 1;

        while (j < n && depth > 0) {
            if (s[j] == '[') depth++;
            else if (s[j] == ']') depth--;
            j++;
        }

        if (depth == 0) {
            string part = s.substr(i, j - i);

            bool hasDigit = false;
            for (char c : part) {
                if (isdigit((unsigned char)c)) {
                    hasDigit = true;
                    break;
                }
            }

            if (hasDigit) {
                arrays.push_back(parseOneArray(part));
            }

            i = j - 1;
        }
    }

    return arrays;
}

