};

void push(struct StackNode** top, int val) {
    struct StackNode* node = (struct StackNode*)malloc(sizeof(struct StackNode));
    node->val = val;
    node->next = *top;
    *top = node;
}

int pop(struct StackNode** top) {
    struct StackNode* temp = *top;
    int val = temp->val;
    *top = temp->next;
    free(temp);
    return val;
}

int isEmpty(struct StackNode* top) {
