    public static ListNode deleteDuplicatesUnsorted(ListNode head) {
        HashMap<Integer, Integer> freq = new HashMap<>();

        ListNode curr = head;

        while (curr != null) {
            freq.put(curr.val, freq.getOrDefault(curr.val, 0) + 1);
            curr = curr.next;
        }

        ListNode dummy = new ListNode(0);
        dummy.next = head;

        ListNode prev = dummy;
        curr = head;

        while (curr != null) {
            if (freq.get(curr.val) > 1) {
                prev.next = curr.next;
            } else {
                prev = curr;
            }

            curr = curr.next;
        }

        return dummy.next;
