    strncpy(listPart, l + 1, len);
    listPart[len] = '\0';

    int values[1000];
    int count = extractNumbers(listPart, values);

    struct ListNode* head = buildList(values, count);
    head = removeZeroSumSublists(head);

    printList(head);

    return 0;
}

#include <iostream>
#include <unordered_map>
#include <vector>
#include <string>
#include <cctype>
using namespace std;

struct ListNode {
    int val;
    ListNode* next;

    ListNode(int x) {
        val = x;
        next = nullptr;
    }
};

class Solution {
public:
    ListNode* removeZeroSumSublists(ListNode* head) {

        ListNode* dummy = new ListNode(0);
        dummy->next = head;

        unordered_map<int, ListNode*> seen;

        int prefixSum = 0;
        ListNode* curr = dummy;

        while (curr) {
            prefixSum += curr->val;
            seen[prefixSum] = curr;
            curr = curr->next;
        }

        prefixSum = 0;
        curr = dummy;

        while (curr) {
            prefixSum += curr->val;
            curr->next = seen[prefixSum]->next;
            curr = curr->next;
        }

        return dummy->next;
    }
};

vector<int> extractNumbers(const string& s) {
    vector<int> nums;
    int n = s.size();

    for (int i = 0; i < n;) {
        if (isdigit(s[i]) || (s[i]=='-' && i+1<n && isdigit(s[i+1]))) {

            int sign = 1;
            if (s[i]=='-') {
                sign = -1;
                i++;
            }

            int val = 0;
            while (i<n && isdigit(s[i])) {
                val = val*10 + (s[i]-'0');
                i++;
            }

            nums.push_back(sign*val);
        }
        else {
            i++;
        }
    }

    return nums;
}

ListNode* buildList(const vector<int>& vals) {

    if (vals.empty()) return nullptr;

    ListNode* head = new ListNode(vals[0]);
    ListNode* curr = head;

    for (int i = 1; i < vals.size(); i++) {
        curr->next = new ListNode(vals[i]);
        curr = curr->next;
    }

    return head;
}

void printList(ListNode* head) {

    cout << "[";

    while (head) {
        cout << head->val;
        head = head->next;

        if (head) cout << ",";
    }

    cout << "]";
}

int main() {

    string input,line;

    while (getline(cin,line)) {
        if (!input.empty()) input += "\n";
        input += line;
    }

    size_t l = input.find('[');
    size_t r = input.find(']',l);

    if (l==string::npos || r==string::npos) {
        cout<<"[]";
        return 0;
    }

    string part = input.substr(l+1,r-l-1);

    vector<int> vals = extractNumbers(part);

    ListNode* head = buildList(vals);

    Solution obj;
    head = obj.removeZeroSumSublists(head);

    printList(head);

    return 0;
}
